def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    div_rows = {
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    }
    div_cols = {
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    }

    def regions(size, dividers):
        result, start = [], 0
        for i in range(size):
            if i in dividers:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < size:
            result.append((start, size))
        return result

    row_regions = regions(h, div_rows)
    col_regions = regions(w, div_cols)
    boxes = [
        (r0, r1, c0, c1)
        for r0, r1 in row_regions
        for c0, c1 in col_regions
    ]

    def contents(box):
        r0, r1, c0, c1 = box
        return [
            (r - r0, c - c0, grid[r][c])
            for r in range(r0, r1)
            for c in range(c0, c1)
            if grid[r][c] != background
        ]

    source = max(boxes, key=lambda box: len(contents(box)))
    sr0, sr1, sc0, sc1 = source
    motif = contents(source)

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in boxes:
        if (r1 - r0, c1 - c0) == (sr1 - sr0, sc1 - sc0):
            for dr, dc, color in motif:
                out[r0 + dr][c0 + dc] = color

    return out
